(()=>{'use strict';const b=document.querySelector('#hold-join');if(!b)return;let invite='https://discord.gg/HgcbPjcyJ',timer=null,ready=false,active=false,start=null;const label=b.querySelector('.hold-label'),status=document.querySelector('.hold-status');fetch('community.json').then(r=>r.json()).then(c=>{try{const u=new URL(c.discordInvite);if(u.protocol==='https:'&&['discord.gg','discord.com'].includes(u.hostname))invite=u.href;}catch{}}).catch(()=>{});function reset(){clearTimeout(timer);timer=null;ready=false;active=false;start=null;b.classList.remove('holding','ready');label.textContent='Hold to join Discord';}function begin(){if(active)return;active=true;ready=false;b.classList.add('holding');label.textContent='Keep holding…';status.textContent='Hold for one second.';timer=setTimeout(()=>{if(!active)return;ready=true;b.classList.add('ready');label.textContent='Release to join';status.textContent='Ready. Release to open Discord.';},1000);}function release(){const open=active&&ready;reset();if(open)window.location.assign(invite);}b.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={x:e.clientX,y:e.clientY};b.setPointerCapture(e.pointerId);begin();});b.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>20)reset();});b.addEventListener('pointerup',release);b.addEventListener('pointercancel',reset);b.addEventListener('lostpointercapture',reset);b.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();if(!e.repeat)begin();}if(e.key==='Escape')reset();});b.addEventListener('keyup',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();release();}});b.addEventListener('click',e=>{e.preventDefault();if(e.detail===0&&!active)window.location.assign(invite);});b.addEventListener('blur',reset);document.addEventListener('visibilitychange',()=>{if(document.hidden)reset();});})();
